import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.delete;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

import io.github.marishasahay.shortener.IntegrationTestSupport;
import java.time.Duration;
import java.util.UUID;
import org.junit.jupiter.api.Test;

/** Issue #1 end to end: the cache must never extend a link's life. */
class CachedLinkExpiryIT extends IntegrationTestSupport {

  private String create(String expiry) throws Exception {
    String alias = "e-" + UUID.randomUUID().toString().substring(0, 12);
    postLink("{\"url\": \"https://example.com/sale\", \"customAlias\": \"" + alias + "\""
        + (expiry == null ? "" : ", \"expiresAt\": \"" + expiry + "\"") + "}")
        .andExpect(status().isCreated());
    return alias;
  }

  @Test
  void aCachedLinkStopsRedirectingTheMomentItExpires() throws Exception {
    String code = create("2026-01-01T01:00:00Z");
    mockMvc.perform(get("/" + code)).andExpect(status().isFound());
    clock.advance(Duration.ofMinutes(59));
    mockMvc.perform(get("/" + code)).andExpect(status().isFound());

    clock.advance(Duration.ofMinutes(1));

    mockMvc.perform(get("/" + code)).andExpect(status().isGone());
  }

  @Test
  void aDeletedCachedLinkStopsRedirectingImmediately() throws Exception {
    String code = create(null);
    mockMvc.perform(get("/" + code)).andExpect(status().isFound());

    mockMvc.perform(delete("/api/v1/links/" + code)).andExpect(status().isNoContent());

    mockMvc.perform(get("/" + code)).andExpect(status().isNotFound());
  }
}
"}, {"path": "src/test/java/io/github/marishasahay/shortener/link/LinkResolverTest.java", "content": "package io.github.marishasahay.shortener.link;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

import com.github.benmanes.caffeine.cache.Caffeine;
import io.github.marishasahay.shortener.support.MutableClock;
import java.time.Instant;
import java.util.Optional;
import org.junit.jupiter.api.Test;

class LinkResolverTest {

  private static final Instant NOW = Instant.parse("2026-01-01T00:00:00Z");
  private static final String TARGET = "https://example.com/";

  private final LinkRepository repository = mock(LinkRepository.class);
  private final MutableClock clock = new MutableClock(NOW);
  private final LinkResolver resolver =
      new LinkResolver(Caffeine.newBuilder().build(), repository, clock);

  @Test
  void shouldLoadTargetFromRepositoryOnCacheMiss() {
    when(repository.findActiveByCode("abcdefg")).thenReturn(Optional.of(link(null)));

    assertThat(resolver.resolve("abcdefg")).isEqualTo(TARGET);
  }

  @Test
  void shouldServeRepeatedLookupsFromCache() {
    when(repository.findActiveByCode("abcdefg")).thenReturn(Optional.of(link(null)));

    resolver.resolve("abcdefg");
    resolver.resolve("abcdefg");

    verify(repository, times(1)).findActiveByCode("abcdefg");
  }

  @Test
  void shouldThrowNotFoundAndNotCacheUnknownCodes() {
    when(repository.findActiveByCode("missing")).thenReturn(Optional.empty());

    assertThatThrownBy(() -> resolver.resolve("missing"))
        .isInstanceOf(LinkNotFoundException.class);
    assertThatThrownBy(() -> resolver.resolve("missing"))
        .isInstanceOf(LinkNotFoundException.class);
    verify(repository, times(2)).findActiveByCode("missing");
  }

  @Test
  void shouldThrowGoneWhenLinkLoadedFromDatabaseHasExpired() {
    when(repository.findActiveByCode("abcdefg"))
        .thenReturn(Optional.of(link(NOW.minusSeconds(1))));

    assertThatThrownBy(() -> resolver.resolve("abcdefg"))
        .isInstanceOf(LinkExpiredException.class);
  }

  @Test
  void shouldTreatExpiryInstantItselfAsExpired() {
    when(repository.findActiveByCode("abcdefg")).thenReturn(Optional.of(link(NOW)));

    assertThatThrownBy(() -> resolver.resolve("abcdefg"))
        .isInstanceOf(LinkExpiredException.class);
  }

  @Test
  void shouldReturnGoneWhenACachedLinkExpiresIssue1() {
    when(repository.findActiveByCode("abcdefg"))
        .thenReturn(Optional.of(link(NOW.plusSeconds(60))));
    assertThat(resolver.resolve("abcdefg")).isEqualTo(TARGET);

    clock.setInstant(NOW.plusSeconds(60));

    assertThatThrownBy(() -> resolver.resolve("abcdefg"))
        .isInstanceOf(LinkExpiredException.class);
    verify(repository, times(1)).findActiveByCode("abcdefg");
  }

  @Test
  void shouldKeepServingACachedLinkUntilItsExpiry() {
    when(repository.findActiveByCode("abcdefg"))
        .thenReturn(Optional.of(link(NOW.plusSeconds(60))));
    resolver.resolve("abcdefg");

    clock.setInstant(NOW.plusSeconds(59));

    assertThat(resolver.resolve("abcdefg")).isEqualTo(TARGET);
  }

  @Test
  void shouldStopServingADeletedLinkImmediatelyEvenWhenCached() {
    when(repository.findActiveByCode("abcdefg")).thenReturn(Optional.of(link(null)));
    resolver.resolve("abcdefg");

    resolver.evict("abcdefg");
    when(repository.findActiveByCode("abcdefg")).thenReturn(Optional.empty());

    assertThatThrownBy(() -> resolver.resolve("abcdefg"))
        .isInstanceOf(LinkNotFoundException.class);
  }

  private static Link link(Instant expiresAt) {
    return new Link(1L, "abcdefg", TARGET, NOW.minusSeconds(3600), expiresAt);
  }
}
